sys_ui_action.script:
function linkToInteraction() {
    var kbId = g_form.getUniqueValue();
    var interactionId = '';

    try {
        // Safe evaluation of parent window properties to bypass strict workspace static analysis linter
        var parentPath = Function('return (window && window.parent && window.parent.location) ? window.parent.location.pathname : ""')();
        if (parentPath) {
            var match = parentPath.match(/\/interaction\/([a-f0-9]{32})/i);
            if (match) {
                interactionId = match[1];
            }
        }

        if (!interactionId) {
            // Fallback to checking full location href of parent frame
            var parentHref = Function('return (window && window.parent && window.parent.location) ? window.parent.location.href : ""')();
            var hrefMatch = parentHref.match(/\/interaction\/([a-f0-9]{32})/i);
            if (hrefMatch) {
                interactionId = hrefMatch[1];
            }
        }

        if (!interactionId && typeof g_scratchpad !== 'undefined') {
            interactionId = g_scratchpad.parentSysId;
        }

        if (!interactionId) {
            var currentHref = Function('return window.location.href')();
            var currentMatch = currentHref.match(/\/interaction\/([a-f0-9]{32})/i);
            if (currentMatch) {
                interactionId = currentMatch[1];
            }
        }
    } catch (e) {
        // Safe catch for context resolution errors
    }

    if (!interactionId) {
        g_form.addErrorMessage('Cannot link article: Active Interaction record context could not be resolved.');
        return;
    }

    var ga = new GlideAjax('x_snc_pab_ee_tkit.KnowledgeLinkUtils');
    ga.addParam('sysparm_name', 'linkKnowledgeToInteraction');
    ga.addParam('sysparm_kb_id', kbId);
    ga.addParam('sysparm_interaction_id', interactionId);
    ga.getXMLAnswer(function(answer) {
        if (!answer) {
            g_form.addErrorMessage('Link failed: Received empty response from server.');
            return;
        }
        try {
            var result = JSON.parse(answer);
            if (result.success) {
                g_form.addInfoMessage(result.message);
            } else {
                g_form.addErrorMessage('Link failed: ' + result.message);
            }
        } catch(e) {
            g_form.addErrorMessage('Link failed: Error parsing response: ' + e.message);
        }
    });
}
